import * as Cookie  from "./cookie";
import * as Util from "./util";

declare const WXLocaleironment: any;

export enum LOCALE_KEY_NAME {
  region = 'region',
  lang = 'lang',
  currency = 'currency',
  tz = 'tz',
}


export interface LocaleObject{
  [key: string]: string; // Add index signature
}

export interface GetLocaleOptions{
  short?: boolean;
}

export interface LocaleOptions{
  key?: string;
  maxAge?: number;
  domain?: string;
  path?: string;
}


class Locale {
  private key: string;

  private maxAge?: number;
  
  private domain?: string;

  private path?: string;
  
  private container: string;

  [key: string]: any;

  constructor(options: LocaleOptions = {}) {
    this.key = options.key || '';
    this.maxAge = options.maxAge;
    this.domain = options.domain;
    this.path = options.path;
    this.container = Util.getContainerType();
  }

  getKey(): string {
    return this.key;
  }

  getPureLocale(): LocaleObject{
    const localeObject = this[this.container] ? this[this.container]() : "";
    return localeObject;
  }

  /**
   * get locale object = > {regin: 'CN', lang: 'zh-CN', currency: 'CNY', tz: 'Asia/Shanghai'}
   * @param options 
   */
  getLocale(options?: GetLocaleOptions): LocaleObject {
    const localeObject = this.getPureLocale();
    if(options && options.short && localeObject[LOCALE_KEY_NAME.lang]){
      const shortLang = localeObject[LOCALE_KEY_NAME.lang].split('-')[0];
      localeObject[LOCALE_KEY_NAME.lang] = shortLang;
    }
    // for compatible common-info:  http://gitlab.alibaba-inc.com/lzdmod/common-info
    if(localeObject.region)localeObject.regionID = localeObject.region;
    if(localeObject.lang) localeObject.language = localeObject.lang;
    return localeObject;
  }

  /**
   * get locale object for compatible common-info:  http://gitlab.alibaba-inc.com/lzdmod/common-info
   * @param options {short: true/false}
   */
  getEnv(options?: GetLocaleOptions): LocaleObject{
    const op = Object.assign({},{short: true}, options);
    const localeObject  = this.getLocale(op);
    return localeObject;
  }

  /**
   * get locale string = > regin=CN&lang=zh-CN&currency=CNY&tz=Asia/Shanghai
   * @param options 
   */
  getLocaleString(): string{
    const locale: LocaleObject = this.getPureLocale();
    return Util.stringifyToQueryString(locale);
  }

  /**
   * set locale use key and value
   * @param key the key of locale id. by default: region represent countries, dependent territories, and special areas of geographical interest , lang represent language tag , currency represent currency , tz represent time zone
   * @param value the value, in specification, region use ISO 3166-1 alpha-2 , lang use BCP-47 , currency use ISO 4217  , tz use IANA timezone code
   */
  setLocale(key: string, value: string): void{
    if(!key) return;
    const object = {[key]: value};
    this.setLocaleWithObject(object);
  }

  /**
   * set region
   * @param code region code , use ISO 3166-1 alpha-2 
   */
  setRegion(code: string): void {
    if(!code) return;
    this.setLocale(LOCALE_KEY_NAME.region, code);
  }
  
  /**
   * set language
   * @param code language tag , use BCP-47
   */
  setLang(code: string): void {
    if(!code) return;
    this.setLocale(LOCALE_KEY_NAME.lang, code);
  }
  
  /**
   * set currency code 
   * @param code currency code , use ISO 4217
   */
  setCurrency(code: string): void {
    if(!code) return;
    this.setLocale(LOCALE_KEY_NAME.currency, code);
  }
  
  /**
   * set time zone
   * @param code set time zone, use iana code 
   */
  setTimeZone(code: string): void {
    if(!code) return;
    this.setLocale(LOCALE_KEY_NAME.tz, code);
  }

  setLocaleWithObject(object: LocaleObject): void{
    if(this.container === Util.ContainerType.weex) return;
    const currentLocale = this.getLocale(); 
    const mergedLocale = Object.assign({}, currentLocale, object);
    const strValue = Util.stringifyToQueryString(mergedLocale);
    Cookie.set(this.key, strValue, {
      path: this.path || '/',
      maxAge: this.maxAge, // to second
      domain: this.domain,
    });
  }

  weex(): LocaleObject {
    let str = "";
    if (typeof WXLocaleironment === "object") { 
      str = (WXLocaleironment && WXLocaleironment[this.key]) || ""; // eslint-disable-line
    }
    const localeObject =  Util.parseQueryString(str);
    return localeObject
  }  
  
  web(): LocaleObject {
    let str = "";
    let localeObject: LocaleObject = {};
    // try to get from url query
    if(location&&location.search){ // eslint-disable-line 
      const search = location.search.replace(/^[?#&]/, ''); // eslint-disable-line
      const keysAndValue = Util.parseQueryString(search);
      const keyNames = Util.objectValues(LOCALE_KEY_NAME as {[key: string]: any});
      Object.keys(keysAndValue).forEach((key): void=>{
        if(keyNames.indexOf(key)>=0/* &&keysAndValue[key] */){
          localeObject[key] = keysAndValue[key];
        }
      });
    }
    // try to get from _i18n_ inject by app: WindVane
    if (typeof window === "object") {
      const win: {[key: string]: any} = (window as any);
      str = (window as any)[this.key]; // windows['x-hng']
      if(str){
        const windowLocale = Util.parseQueryString(str);
        localeObject = Object.assign({},windowLocale, localeObject);
      }else if(typeof win.g_config === 'object'){
        const {regionID,language} = win.g_config;  // read from window.g_config
        const localeFromGConfig: {[key: string]: any} = {};
        if(regionID) localeFromGConfig[LOCALE_KEY_NAME.region] = regionID;
        if(language) localeFromGConfig[LOCALE_KEY_NAME.lang] = language;
        localeObject = Object.assign({},localeFromGConfig, localeObject);
      }
    }
    
    

    // try to get from cookie
    if (!str) {
      let cookieLocale: {[key: string]: string} = {};
      str = Cookie.get(this.key); // x-hng 
      if(!str){ // if has not x-hng ,read from hng
        const hng  = Cookie.get('hng');
        if(hng){
          const hngArray = hng.split('|');
          if(hngArray[0]) cookieLocale[LOCALE_KEY_NAME.region] = hngArray[0]; // eslint-disable-line
          if(hngArray[1]) cookieLocale[LOCALE_KEY_NAME.lang] = hngArray[1]; // eslint-disable-line
          if(hngArray[2]) cookieLocale[LOCALE_KEY_NAME.currency] = hngArray[2]; // eslint-disable-line
        }
      }else {
        cookieLocale = Util.parseQueryString(str);
      }
      localeObject = Object.assign({},cookieLocale, localeObject);
    }
    return localeObject
  }

  clear(): void{
    Cookie.remove(this.key);
  }
}

export default Locale;